PRAGMA foreign_keys=ON;
CREATE TABLE ingredients(id TEXT PRIMARY KEY,name TEXT NOT NULL); CREATE TABLE stocks(ingredient_id TEXT PRIMARY KEY REFERENCES ingredients(id),quantity REAL NOT NULL CHECK(quantity>=0),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE menus(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1); CREATE TABLE recipes(menu_id TEXT REFERENCES menus(id),ingredient_id TEXT REFERENCES ingredients(id),quantity REAL NOT NULL CHECK(quantity>0),PRIMARY KEY(menu_id,ingredient_id));
CREATE TABLE orders(id TEXT PRIMARY KEY,status TEXT NOT NULL CHECK(status IN('open','paid','cancelled')),created_at TEXT NOT NULL); CREATE TABLE order_items(order_id TEXT REFERENCES orders(id),menu_id TEXT REFERENCES menus(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL,PRIMARY KEY(order_id,menu_id));
CREATE TABLE payments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),method TEXT NOT NULL,amount INTEGER NOT NULL,created_at TEXT NOT NULL); CREATE TABLE stock_movements(id TEXT PRIMARY KEY,ingredient_id TEXT REFERENCES ingredients(id),order_id TEXT REFERENCES orders(id),delta REAL NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE stock_overrides(id TEXT PRIMARY KEY,order_id TEXT NOT NULL,actor_id TEXT NOT NULL,reason TEXT NOT NULL,consumed_at TEXT); CREATE TABLE sync_mutations(device_id TEXT NOT NULL,mutation_id TEXT NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(device_id,mutation_id));
CREATE TABLE receipts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,path TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,parser_status TEXT NOT NULL,parser_json TEXT,created_at TEXT NOT NULL);
